from __future__ import annotations

import json
import logging

import requests

log = logging.getLogger("notifiers")


class RequestsHelper:

    @classmethod
    def request(
        self,
        url: str,
        method: str,
        raise_for_status: bool = True,
        path_to_errors: tuple | None = None,
        *args,
        **kwargs,
    ) -> tuple:
        session = kwargs.get("session", requests.Session())
        if "timeout" not in kwargs:
            kwargs["timeout"] = (5, 20)
        log.debug(
            "sending a %s request to %s with args: %s kwargs: %s",
            method.upper(),
            url,
            args,
            kwargs,
        )

        if raise_for_status:
            try:
                rsp = session.request(method, url, *args, **kwargs)
                log.debug("response: %s", rsp.text)
                errors = None
                rsp.raise_for_status()
            except requests.RequestException as e:
                if e.response is not None:
                    rsp = e.response
                    if path_to_errors:
                        try:
                            errors = rsp.json()
                            for arg in path_to_errors:
                                if errors.get(arg):
                                    errors = errors[arg]
                        except json.decoder.JSONDecodeError:
                            errors = [rsp.text]
                    else:
                        errors = [rsp.text]
                    if not isinstance(errors, list):
                        errors = [errors]
                else:
                    rsp = None
                    errors = [str(e)]
                log.debug("errors when trying to access %s: %s", url, errors)
        log.debug("returning response %s, errors %s", rsp, errors)
        return rsp, errors


def get(url: str, *args, **kwargs) -> tuple:
